23	/// A key for a scope, used to link a [`ResolvedCommand#structfield.scope`] to the store [`Resolved#structfield.scopes`].
24	pub type ScopeKey = u64;
25	
26	/// Metadata for what referenced a [`ResolvedCommand`].
27	#[cfg(debug_assertions)]
28	#[derive(Debug, Clone, Hash, PartialEq, Eq)]
29	pub struct ResolvedCommandReference {
30	  /// Identifier of the capability.
31	  pub capability: String,
32	  /// Identifier of the permission.
33	  pub permission: String,
34	}
35	
36	/// A resolved command permission.
37	#[derive(Default, Clone, PartialEq, Eq)]
38	pub struct ResolvedCommand {
39	  /// The list of capability/permission that referenced this command.
40	  #[cfg(debug_assertions)]
41	  pub referenced_by: Vec<ResolvedCommandReference>,
42	  /// The list of window label patterns that was resolved for this command.
43	  pub windows: Vec<glob::Pattern>,
44	  /// The list of webview label patterns that was resolved for this command.
45	  pub webviews: Vec<glob::Pattern>,
46	  /// The reference of the scope that is associated with this command. See [`Resolved#structfield.scopes`].
47	  pub scope: Option<ScopeKey>,
48	}
49	
50	impl fmt::Debug for ResolvedCommand {
51	  fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
52	    f.debug_struct("ResolvedCommand")
53	      .field("windows", &self.windows)
54	      .field("webviews", &self.webviews)
55	      .field("scope", &self.scope)
56	      .finish()
57	  }
58	}
