28	/// The runtime authority used to authorize IPC execution based on the Access Control List.
29	pub struct RuntimeAuthority {
30	  acl: BTreeMap<String, crate::utils::acl::manifest::Manifest>,
31	  allowed_commands: BTreeMap<CommandKey, ResolvedCommand>,
32	  denied_commands: BTreeMap<CommandKey, ResolvedCommand>,
33	  pub(crate) scope_manager: ScopeManager,
34	}
35	
36	/// The origin trying to access the IPC.
37	pub enum Origin {
38	  /// Local app origin.
39	  Local,
40	  /// Remote origin.
41	  Remote {
42	    /// Remote URL.
43	    url: String,
44	  },
45	}
46	
47	impl Display for Origin {
48	  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
49	    match self {
50	      Self::Local => write!(f, "local"),
51	      Self::Remote { url } => write!(f, "remote: {url}"),
52	    }
53	  }
54	}
55	
56	impl Origin {
57	  fn matches(&self, context: &ExecutionContext) -> bool {
58	    match (self, context) {
59	      (Self::Local, ExecutionContext::Local) => true,
60	      (Self::Remote { url }, ExecutionContext::Remote { url: url_pattern }) => {
61	        url_pattern.matches(url)
62	      }
63	      _ => false,
64	    }
65	  }
66	}
67	
68	/// A capability that can be added at runtime.
69	pub trait RuntimeCapability {
70	  /// Creates the capability file.
71	  fn build(self) -> CapabilityFile;
72	}
73	
74	impl<T: AsRef<str>> RuntimeCapability for T {
75	  fn build(self) -> CapabilityFile {
76	    self.as_ref().parse().expect("invalid capability")
77	  }
78	}
79	
80	/// A builder for a [`Capability`].
81	pub struct CapabilityBuilder(Capability);
82	
83	impl CapabilityBuilder {
84	  /// Creates a new capability builder with a unique identifier.
85	  pub fn new(identifier: impl Into<String>) -> Self {
86	    Self(Capability {
87	      identifier: identifier.into(),
88	      description: "".into(),
89	      remote: None,
90	      local: true,
91	      windows: Vec::new(),
92	      webviews: Vec::new(),
93	      permissions: Vec::new(),
94	      platforms: Vec::new(),
95	    })
96	  }
97	
98	  /// Allows this capability to be used by a remote URL.
99	  pub fn remote(mut self, url: String) -> Self {
100	    self
101	      .0
102	      .remote
103	      .get_or_insert_with(Default::default)
104	      .urls
105	      .push(url);
106	    self
107	  }
108	
109	  /// Whether this capability is applied on local app URLs or not. Defaults to `true`.
110	  pub fn local(mut self, local: bool) -> Self {
111	    self.0.local = local;
112	    self
113	  }
114	
115	  /// Link this capability to the given window label.
116	  pub fn window(mut self, window: impl Into<String>) -> Self {
117	    self.0.windows.push(window.into());
118	    self
119	  }
