604	/// Usually you will just rely on [`serde::de::DeserializeOwned`] instead of implementing it manually,
605	/// though this is useful if you need to do some initialization logic on the type itself.
606	pub trait ScopeObject: Sized + Send + Sync + Debug + 'static {
