  commands: BTreeMap<String, Vec<ResolvedCommandTemp>>,
) -> Result<BTreeMap<String, Vec<ResolvedCommand>>, Error> {
  commands
    .into_iter()
    .map(|(name, cmds)| {
      let resolved = cmds
        .into_iter()
        .map(|cmd| {
