            referenced_by: cmd.referenced_by,
            context: cmd.context,
            windows: parse_glob_patterns(cmd.windows)?,
            webviews: parse_glob_patterns(cmd.webviews)?,
            scope_id: cmd.scope_id,
          })
        })
        .collect::<Result<Vec<_>, Error>>()?;
      Ok((name, resolved))
